const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={saved:[],plan:null,done:[]};try{const s=JSON.parse(localStorage.getItem('eduai-v1'));if(s&&Array.isArray(s.saved)){state.saved=s.saved.filter(id=>UNIVERSITIES.some(u=>u.id===id)).slice(0,3);if(s.plan&&['interest','stage','destination','start'].every(k=>typeof s.plan[k]==='string')&&/^\d{4}-\d{2}$/.test(s.plan.start))state.plan=s.plan;state.done=Array.isArray(s.done)?s.done.filter(n=>Number.isInteger(n)&&n>=0&&n<6):[]}}catch{}
let savedOnly=false;function notice(t){$('#notice').textContent=t;$('#notice').style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#notice').style.display='none',3500)}function persist(){try{localStorage.setItem('eduai-v1',JSON.stringify(state))}catch{notice('Browser storage is unavailable. Keep this tab open or export your plan.')}}
function render(){const term=$('#search').value.toLowerCase().trim();const list=UNIVERSITIES.filter(u=>(!$('#country').value||u.country===$('#country').value)&&(!savedOnly||state.saved.includes(u.id))&&`${u.name} ${u.city} ${u.country}`.toLowerCase().includes(term));$('#results').textContent=`${list.length} universities to explore`;$('#count').textContent=state.saved.length;$('#cards').innerHTML=list.length?list.map(u=>`<article class="card"><div class="card-art ${u.color}"><span class="monogram">${u.symbol}</span><span class="location">${u.city.toUpperCase()} / ${u.country.toUpperCase()}</span><button class="save" data-save="${u.id}" aria-label="${state.saved.includes(u.id)?'Remove':'Save'} ${u.name}" aria-pressed="${state.saved.includes(u.id)}">${state.saved.includes(u.id)?'♥':'♡'}</button></div><div class="card-body"><h3>${u.name}</h3><p>${u.tag}</p><button class="details" data-profile="${u.id}">Explore university <span style="float:right">↗</span></button></div></article>`).join(''):'<div class="empty">No universities match these filters. Try another destination or clear your search.</div>';const selected=UNIVERSITIES.filter(u=>state.saved.includes(u.id));$('#comparison').innerHTML=selected.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Your shortlist</th>${selected.map(u=>`<th scope="col">${u.name}<br><button class="outline" data-save="${u.id}">Remove</button></th>`).join('')}</tr></thead><tbody>${[['Destination',u=>`${u.city}, ${u.country}`],['Study level',()=> 'Undergraduate'],['Application route',u=>u.route],['What to check',u=>u.requirement],['Tuition & scholarships',()=> 'Check current programme fees and funding on the official website.'],['Official information',u=>`<a href="${u.source}" target="_blank" rel="noopener">Admissions guide ↗</a>`]].map(([label,fn])=>`<tr><th scope="row">${label}</th>${selected.map(u=>`<td>${fn(u)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">♡ &nbsp; A few good possibilities belong here.<br>Tap the heart on a university to start your comparison.</div>'}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;if(state.saved.includes(id))state.saved=state.saved.filter(x=>x!==id);else if(state.saved.length<3)state.saved.push(id);else return notice('Your comparison holds three universities. Remove one to add another.');persist();render()}const profile=e.target.closest('[data-profile]');if(profile){const u=UNIVERSITIES.find(x=>x.id===profile.dataset.profile);$('#profile-body').innerHTML=`<div class="eyebrow">${u.city} / ${u.country}</div><h2>${u.name}</h2><p>${u.description}</p><h3>Before you apply</h3><p>${u.requirement}</p><h3>Budget & timing</h3><p>Tuition, scholarships and application dates vary by programme and intake. Check the official guide for your course and student category before making a decision.</p><a class="primary" href="${u.source}" target="_blank" rel="noopener">Official admissions guide ↗</a><p class="small">Source reviewed ${u.reviewed}. This profile is a starting point, not an admission assessment.</p>`;$('#profile').showModal()}});$('.close').onclick=()=>$('#profile').close();$('#profile').addEventListener('click',e=>{if(e.target===$('#profile')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#search').oninput=render;$('#country').onchange=render;$('#saved-filter').onclick=()=>{savedOnly=!savedOnly;$('#saved-filter').setAttribute('aria-pressed',savedOnly);render()};
function tasks(){const p=state.plan;return [{title:`Explore ${p.interest} programmes in ${p.destination==='Still exploring'?'your preferred destinations':p.destination}`,months:12,note:`Starting from: ${p.stage}. Compare course structure, entry route and qualification eligibility.`},{title:'Confirm prerequisites and language requirements',months:10,note:'Check each programme’s official requirements; book a language test only if needed.'},{title:'Build your budget and funding shortlist',months:9,note:'Record tuition, living costs and scholarship eligibility from official sources.'},{title:'Prepare your application documents',months:6,note:p.stage==='University / transfer'?'Gather university transcripts and check transfer-credit rules.':'Gather transcripts, references and any required personal statement or portfolio.'},{title:'Verify deadlines and submit applications',months:4,note:'Replace this suggested target with each university’s actual deadline, which may be earlier.'},{title:'Review offers and prepare your move',months:2,note:'After an offer, confirm acceptance conditions, housing and any required student visa.'}]}
function target(months){const [y,m]=state.plan.start.split('-').map(Number);return new Date(y,m-1-months,1).toLocaleDateString('en-GB',{month:'short',year:'numeric'})}
function renderPlan(){if(!state.plan){$('#plan-output').innerHTML='<div class="eyebrow">A PLAN THAT STARTS WITH YOU</div><h3>From “what if” to “what’s next”.</h3><p>Tell us what you want to study and when you want to begin. Your pathway will bring the research, documents and preparation into one manageable checklist.</p><div class="empty">01 &nbsp; Explore your options<br>02 &nbsp; Prepare your application<br>03 &nbsp; Get ready for your next chapter</div>';return}const p=state.plan;$('#plan-output').innerHTML=`<div class="roadmap-top"><div><div class="eyebrow">YOUR PERSONAL PATHWAY</div><h3>${esc(p.interest)}</h3></div><button id="export" class="outline">Export ↓</button></div><p class="small">${esc(p.destination)} · Intended start ${esc(p.start)} · ${state.done.length} of 6 complete</p><div class="progress" role="progressbar" aria-label="Pathway completion" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${state.done.length}"><i style="width:${state.done.length/6*100}%"></i></div>${tasks().map((t,i)=>`<label class="task"><input type="checkbox" data-task="${i}" ${state.done.includes(i)?'checked':''}><span>${esc(t.title)}<small>Suggested target: ${target(t.months)} · ${esc(t.note)}</small></span></label>`).join('')}<p class="small">These are planning suggestions, not university deadlines. If a suggested date has passed, prioritize that task now. Your checklist stays saved when you return to this browser.</p>`;$('#export').onclick=()=>{const content=`EDUAI — My study pathway\n${p.interest} | ${p.destination} | Start: ${p.start}\n\n`+tasks().map((t,i)=>`${state.done.includes(i)?'[x]':'[ ]'} ${t.title}\nSuggested target: ${target(t.months)}\n${t.note}`).join('\n\n')+'\n\nSuggested planning dates only. Verify official deadlines.';const url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='eduai-study-pathway.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
$('#plan-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.interest=data.interest.trim();if(!data.interest)return notice('Enter a study interest to create your pathway.');const now=new Date();const month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;if(data.start<month)return notice('Choose this month or a future month for your study start.');if(state.plan&&JSON.stringify(state.plan)!==JSON.stringify(data)&&state.done.length&&!confirm('Replace your pathway and reset completed steps?'))return;const same=state.plan&&JSON.stringify(state.plan)===JSON.stringify(data);state.plan=data;if(!same)state.done=[];persist();renderPlan();notice('Your pathway is ready and saved.');};$('#plan-output').onchange=e=>{if(e.target.matches('[data-task]')){const id=Number(e.target.dataset.task);state.done=e.target.checked?[...new Set([...state.done,id])]:state.done.filter(n=>n!==id);persist();renderPlan()}};if(state.plan)for(const [key,value]of Object.entries(state.plan)){if($('#plan-form').elements[key])$('#plan-form').elements[key].value=value}render();renderPlan();
